import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_D 8
#define TILE_H 8
#define TILE_W 16
#define MAX_OC_BLOCK 8
#define WPT 4
#define HPT 2
#define OW_THREADS (TILE_W/WPT)
#define OH_THREADS (TILE_H/HPT)
__global__ void conv3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int Cin, const int D, const int H, const int W,
    const int Cout, const int K,
    const int stride, const int padding, const int dilation,
    const int groups,
    const int Dout, const int Hout, const int Wout,
    const bool has_bias,
    const int SD, const int SH, const int SW,
    const int num_tiles_d,
    const int oc_block)
{
    extern __shared__ float smem[];
    const int Cin_per_group = Cin / groups;
    const int Cout_per_group = Cout / groups;
    const int num_oc_blocks = Cout / oc_block;
    const int bz = blockIdx.z;
    const int tile_d_idx = bz % num_tiles_d;
    int tmp = bz / num_tiles_d;
    const int ocb = tmp % num_oc_blocks;
    const int n  = tmp / num_oc_blocks;
    const int oc_base = ocb * oc_block;
    const int g = oc_base / Cout_per_group;
    const int ic_start = g * Cin_per_group;
    const int od_start = tile_d_idx * TILE_D;
    const int oh_start = blockIdx.y * TILE_H;
    const int ow_start = blockIdx.x * TILE_W;
    const int id_min = od_start * stride - padding;
    const int ih_min = oh_start * stride - padding;
    const int iw_min = ow_start * stride - padding;
    const int tid = (threadIdx.z * OH_THREADS + threadIdx.y) * OW_THREADS + threadIdx.x;
    const int block_threads = TILE_D * OH_THREADS * OW_THREADS;
    const int in_batch_stride = Cin * D * H * W;
    const int in_ch_stride = D * H * W;
    const int in_h_stride = W;
    const int smem_input_size = Cin_per_group * SD * SH * SW;
    const int w_ic_stride = K * K * K;
    const int w_oc_stride = Cin_per_group * w_ic_stride;
    const int smem_weight_size = oc_block * Cin_per_group * K * K * K;
    float* smem_input = smem;
    float* smem_weight = smem + smem_input_size;
    const float* in_n = input + n * in_batch_stride;
    for (int idx_s = tid; idx_s < smem_input_size; idx_s += block_threads) {
        int rem = idx_s;
        const int sw = rem % SW; rem /= SW;
        const int sh = rem % SH; rem /= SH;
        const int sd = rem % SD; rem /= SD;
        const int icg = rem;
        const int ic = ic_start + icg;
        const int id = id_min + sd;
        const int ih = ih_min + sh;
        const int iw = iw_min + sw;
        float v = 0.0f;
        if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W) {
            v = __ldg(&in_n[ic * in_ch_stride + id * H * in_h_stride + ih * in_h_stride + iw]);
        }
        smem_input[idx_s] = v;
    }
    for (int idx_w = tid; idx_w < smem_weight_size; idx_w += block_threads) {
        int rem = idx_w;
        const int kw = rem % K; rem /= K;
        const int kh = rem % K; rem /= K;
        const int kd = rem % K; rem /= K;
        const int icg = rem % Cin_per_group; rem /= Cin_per_group;
        const int j = rem;
        const int oc = oc_base + j;
        smem_weight[idx_w] = __ldg(&weight[oc * w_oc_stride + icg * w_ic_stride + kd * K * K + kh * K + kw]);
    }
    __syncthreads();
    const int od = od_start + threadIdx.z;
    const int oh_base = oh_start + threadIdx.y * HPT;
    const int ow_base = ow_start + threadIdx.x * WPT;
    if (od < Dout) {
        float acc[MAX_OC_BLOCK][HPT][WPT];
        #pragma unroll
        for (int j = 0; j < MAX_OC_BLOCK; j++) {
            #pragma unroll
            for (int h = 0; h < HPT; h++) {
                #pragma unroll
                for (int w = 0; w < WPT; w++) acc[j][h][w] = 0.0f;
            }
        }
        const int w_kd_stride = K * K;
        const int SHW = SH * SW;
        for (int icg = 0; icg < Cin_per_group; icg++) {
            const float* s_ic = smem_input + icg * SD * SHW;
            for (int kd = 0; kd < K; kd++) {
                const int sd = threadIdx.z * stride + kd * dilation;
                const float* s_d = s_ic + sd * SHW;
                for (int kh = 0; kh < K; kh++) {
                    const float* s_h_ptrs[HPT];
                    #pragma unroll
                    for (int h = 0; h < HPT; h++) {
                        const int sh = (threadIdx.y * HPT + h) * stride + kh * dilation;
                        s_h_ptrs[h] = s_d + sh * SW;
                    }
                    const float* w_kh_ptr[MAX_OC_BLOCK];
                    #pragma unroll
                    for (int j = 0; j < MAX_OC_BLOCK; j++) {
                        if (j < oc_block) {
                            const float* w_oc = smem_weight + j * w_oc_stride;
                            w_kh_ptr[j] = w_oc + icg * w_ic_stride + kd * w_kd_stride + kh * K;
                        }
                    }
                    for (int kw = 0; kw < K; kw++) {
                        float in_val[HPT][WPT];
                        #pragma unroll
                        for (int h = 0; h < HPT; h++) {
                            #pragma unroll
                            for (int w = 0; w < WPT; w++) {
                                const int sw = (threadIdx.x * WPT + w) * stride + kw * dilation;
                                in_val[h][w] = s_h_ptrs[h][sw];
                            }
                        }
                        #pragma unroll
                        for (int j = 0; j < MAX_OC_BLOCK; j++) {
                            if (j < oc_block) {
                                const float wv = w_kh_ptr[j][kw];
                                #pragma unroll
                                for (int h = 0; h < HPT; h++) {
                                    #pragma unroll
                                    for (int w = 0; w < WPT; w++) {
                                        acc[j][h][w] += in_val[h][w] * wv;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int j = 0; j < MAX_OC_BLOCK; j++) {
            if (j < oc_block) {
                const int oc = oc_base + j;
                const float bval = has_bias ? __ldg(&bias[oc]) : 0.0f;
                #pragma unroll
                for (int h = 0; h < HPT; h++) {
                    const int oh = oh_base + h;
                    if (oh < Hout) {
                        #pragma unroll
                        for (int w = 0; w < WPT; w++) {
                            const int ow = ow_base + w;
                            if (ow < Wout) {
                                float val = acc[j][h][w] + bval;
                                const int out_idx = (((n * Cout + oc) * Dout + od) * Hout + oh) * Wout + ow;
                                output[out_idx] = val;
                            }
                        }
                    }
                }
            }
        }
    }
}
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    const int N = input.size(0);
    const int Cin = input.size(1);
    const int D = input.size(2);
    const int H = input.size(3);
    const int W = input.size(4);
    const int Cout = weight.size(0);
    const int K = weight.size(2);
    const int Dout = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int Wout = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    auto output = torch::empty({N, Cout, Dout, Hout, Wout}, input.options());
    const int num_tiles_d = (Dout + TILE_D - 1) / TILE_D;
    const int num_tiles_h = (Hout + TILE_H - 1) / TILE_H;
    const int num_tiles_w = (Wout + TILE_W - 1) / TILE_W;
    const int SD = (TILE_D - 1) * stride + (K - 1) * dilation + 1;
    const int SH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    const int SW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
    const int Cin_per_group = Cin / groups;
    const int Cout_per_group = Cout / groups;
    int oc_block = 1;
    for (int cand = MAX_OC_BLOCK; cand >= 1; cand--) {
        if (Cout_per_group % cand == 0) { oc_block = cand; break; }
    }
    const int num_oc_blocks = Cout / oc_block;
    const size_t smem_bytes = (size_t)Cin_per_group * SD * SH * SW * sizeof(float) + (size_t)oc_block * Cin_per_group * K * K * K * sizeof(float);
    dim3 block(TILE_W/WPT, TILE_H/HPT, TILE_D);
    dim3 grid(num_tiles_w, num_tiles_h, N * num_oc_blocks * num_tiles_d);
    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    conv3d_kernel<<<grid, block, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, Cin, D, H, W,
        Cout, K,
        stride, padding, dilation,
        groups,
        Dout, Hout, Wout,
        has_bias,
        SD, SH, SW,
        num_tiles_d,
        oc_block
    );
    return output;
}
"""

conv3d_header = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias);
"""

conv3d_module = load_inline(
    name="conv3d_custom",
    cpp_sources=conv3d_header,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if bias:
            fan_in = in_channels // groups * kernel_size * kernel_size * kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda()
        if self.has_bias:
            bias = self.bias.cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return conv3d_module.conv3d_forward(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups,
            self.has_bias
        )

